11	    {
12	      "id": "three-track-convergence",
13	      "insight": "Show the three parallel tracks (research breakthroughs, industry adoption, regulatory action) over 2010–2024, visually emphasizing how their lag gap compresses dramatically around the ChatGPT moment (late 2022)"
14	    },
15	    {
16	      "id": "chatgpt-inflection",
17	      "insight": "Mark the ChatGPT launch (Nov 2022) as a prominent visual anchor point where all three tracks visibly accelerate or cluster, distinguishing the pre- and post-ChatGPT eras"
18	    },
19	    {
20	      "id": "investment-overlay",
21	      "insight": "Overlay annual global AI investment figures along the timeline so the viewer can see how capital surges align with milestone clusters on the three tracks"
22	    },
23	    {
24	      "id": "lag-gap-contrast",
25	      "insight": "Highlight the multi-year gap between research milestones and corresponding regulatory responses in the 2012–2020 period versus the near-simultaneous response in 2023–2024"
26	    },
